package org.brightstats.stats;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
public final class ComponentCopulaChecks {
    static int checks;static void check(boolean condition){checks++;if(!condition)throw new AssertionError("Component copula check "+checks);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid component copula accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{
        Random random=new Random(5153);double[][] data=new double[100][9];for(var row:data){double u=random.nextGaussian(),z=random.nextGaussian(),x=Math.exp(.65*u+.45*random.nextGaussian()),y=.8*x+.4*z+.5*u+.3*random.nextGaussian();double[] scores={x,z,y};for(int block=0;block<3;block++)for(int indicator=0;indicator<3;indicator++)row[block*3+indicator]=scores[block]+.12*random.nextGaussian();}List<String> names=java.util.stream.IntStream.range(0,9).mapToObj(i->"V"+(i+1)).toList();List<PlsSem.Block> blocks=List.of(new PlsSem.Block("X",new int[]{0,1,2},PlsSem.Mode.A),new PlsSem.Block("Z",new int[]{3,4,5},PlsSem.Mode.A),new PlsSem.Block("Y",new int[]{6,7,8},PlsSem.Mode.A));var edges=List.of(new PlsSem.Edge(0,2),new PlsSem.Edge(1,2));var prepared=Gsca.fromBlocks(names,blocks,edges);var pls=ComponentScores.Model.pls(blocks,edges,PlsSem.Options.defaults());var gsca=ComponentScores.Model.gsca(prepared.model(),Gsca.Options.defaults(),prepared.columns());JsonArray cases=new JsonArray();var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();
        for(var model:List.of(pls,gsca))for(var method:CopulaRegression.Method.values())for(var plotting:CopulaRegression.PlottingPosition.values()){
            var specification=new ComponentCopula.Specification(2,new int[]{0},method,plotting);var point=ComponentCopula.fit(data,model,specification);check(point.parents().equals(List.of(0,1)));check(point.correction().observations()==100&&point.correction().coefficients().size()==4);double[][] scores=point.firstStage().scores();for(int column=0;column<3;column++){double mean=0,ss=0;for(var row:scores){mean+=row[column];ss+=row[column]*row[column];}check(Math.abs(mean)<1e-10&&Math.abs(ss-99)<1e-9);}
            JsonObject item=new JsonObject();item.add("observations",gson.toJsonTree(data));item.add("model",gson.toJsonTree(model));item.add("specification",gson.toJsonTree(specification));item.add("point",gson.toJsonTree(point));
            if(plotting==CopulaRegression.PlottingPosition.WEIBULL){var options=new Bootstrap.Options(40,751,.95,method==CopulaRegression.Method.TWO_STAGE_GAUSSIAN?BootstrapIntervals.Method.BCA:BootstrapIntervals.Method.PERCENTILE,RegressionBootstrap.Convention.STANDARD,true);var result=ComponentCopula.bootstrap(data,model,specification,options,null);check(result.inference().successful()==40&&result.inference().failed()==0);check(result.inference().estimates().size()==7);check(result.inference().signHandling().contains("refits the component estimator"));check(result.inference().estimates().stream().noneMatch(e->e.parameter().family().equals("Intercept")));item.add("bootstrapOptions",gson.toJsonTree(options));item.add("bootstrap",gson.toJsonTree(result.inference()));JsonArray draws=new JsonArray();Random drawsRandom=new Random(options.seed());for(int attempt=0;attempt<40;attempt++)draws.add(gson.toJsonTree(Bootstrap.draw(drawsRandom,data.length)));item.add("draws",draws);}
            var numeric=new JsonObject();numeric.add("componentCopula",gson.toJsonTree(point));if(item.has("bootstrap"))numeric.add("bootstrap",item.get("bootstrap"));var archive=org.brightstats.report.ReportArchive.create("COMPONENT_COPULA_TEST",new JsonObject(),numeric,new JsonArray(),List.of());var restored=org.brightstats.report.ComponentCopulaReports.point(archive);check(restored.correction().coefficients().get(1).value()==point.correction().coefficients().get(1).value());if(model.estimator()==ComponentScores.Estimator.PLS)check(Double.isNaN(restored.firstStage().pls().rSquared()[0]));if(item.has("bootstrap"))check(org.brightstats.report.ComponentCopulaReports.bootstrap(archive).successful()==40);
            cases.add(item);
        }
        double[][] original={{-1,-2},{0,0},{1,2}},flipped={{-1,-2},{1,2},{-1,-2},{0,0}};int[] rows={2,0,2,1};double[][] aligned=ComponentScores.align(flipped,original,rows);for(int row=0;row<rows.length;row++)for(int col=0;col<2;col++)check(aligned[row][col]==original[rows[row]][col]);reject(()->ComponentScores.align(new double[][]{{0,0},{0,0}},original,new int[]{0,1}));reject(()->new ComponentCopula.Specification(2,new int[]{2},CopulaRegression.Method.ORIGINAL_GAUSSIAN,CopulaRegression.PlottingPosition.WEIBULL));reject(()->ComponentCopula.fit(data,pls,new ComponentCopula.Specification(0,new int[]{1},CopulaRegression.Method.ORIGINAL_GAUSSIAN,CopulaRegression.PlottingPosition.WEIBULL)));reject(()->ComponentCopula.fit(data,pls,new ComponentCopula.Specification(2,new int[]{0,1},CopulaRegression.Method.TWO_STAGE_GAUSSIAN,CopulaRegression.PlottingPosition.WEIBULL)));
        Thread.currentThread().interrupt();try{ComponentCopula.fit(data,pls,new ComponentCopula.Specification(2,new int[]{0},CopulaRegression.Method.ORIGINAL_GAUSSIAN,CopulaRegression.PlottingPosition.WEIBULL));throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"cases\":"+cases.size()+",\"checks\":"+checks+"}");
    }
}
